create table if not exists public.ce_world_entities (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.ce_tenants(id) on delete cascade,entity_type text not null,canonical_name text not null,attributes jsonb not null default '{}'::jsonb,status text not null default 'ACTIVE' check(status in ('ACTIVE','INACTIVE','ARCHIVED','UNKNOWN')),confidence numeric(5,4) check(confidence is null or(confidence>=0 and confidence<=1)),source text,source_ref text,observed_at timestamptz,valid_from timestamptz not null default now(),valid_until timestamptz,supersedes_id uuid references public.ce_world_entities(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,entity_type,canonical_name));create index if not exists ce_world_entities_tenant_type_idx on public.ce_world_entities(tenant_id,entity_type,status);
create table if not exists public.ce_world_claims (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.ce_tenants(id) on delete cascade,subject_entity_id uuid references public.ce_world_entities(id) on delete cascade,subject_key text not null,predicate text not null,object_value jsonb not null,value_type text not null default 'JSON',domain text,confidence numeric(5,4) check(confidence is null or(confidence>=0 and confidence<=1)),source text,source_ref text,observed_at timestamptz,valid_from timestamptz not null default now(),valid_until timestamptz,status text not null default 'ACTIVE' check(status in ('ACTIVE','SUPERSEDED','RETRACTED','UNVERIFIED','CONTRADICTORY')),supersedes_id uuid references public.ce_world_claims(id) on delete set null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create index if not exists ce_world_claims_lookup_idx on public.ce_world_claims(tenant_id,subject_key,predicate,status);create index if not exists ce_world_claims_domain_idx on public.ce_world_claims(tenant_id,domain,status,observed_at desc);create index if not exists ce_world_claims_freshness_idx on public.ce_world_claims(tenant_id,valid_until,observed_at desc);
create table if not exists public.ce_world_unknowns (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.ce_tenants(id) on delete cascade,domain text not null,question text not null,key text not null,importance text not null default 'MEDIUM' check(importance in ('LOW','MEDIUM','HIGH','CRITICAL')),status text not null default 'OPEN' check(status in ('OPEN','RESOLVED','STALE','BLOCKED')),evidence_needed jsonb not null default '[]'::jsonb,discovered_from jsonb not null default '{}'::jsonb,confidence numeric(5,4) check(confidence is null or(confidence>=0 and confidence<=1)),resolved_by_claim_id uuid references public.ce_world_claims(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),resolved_at timestamptz,unique(tenant_id,domain,key));create index if not exists ce_world_unknowns_open_idx on public.ce_world_unknowns(tenant_id,status,importance);
create table if not exists public.ce_world_contradictions (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.ce_tenants(id) on delete cascade,subject_key text not null,predicate text not null,claim_a_id uuid not null references public.ce_world_claims(id) on delete cascade,claim_b_id uuid not null references public.ce_world_claims(id) on delete cascade,conflict_type text not null default 'VALUE_MISMATCH' check(conflict_type in ('VALUE_MISMATCH','TEMPORAL_OVERLAP','SOURCE_DISAGREEMENT','SCHEMA_MISMATCH')),status text not null default 'OPEN' check(status in ('OPEN','RESOLVED','ACCEPTED_AS_UNCERTAIN','DISMISSED')),resolution text,winning_claim_id uuid references public.ce_world_claims(id) on delete set null,confidence numeric(5,4) check(confidence is null or(confidence>=0 and confidence<=1)),detected_at timestamptz not null default now(),resolved_at timestamptz,metadata jsonb not null default '{}'::jsonb,unique(tenant_id,claim_a_id,claim_b_id));create index if not exists ce_world_contradictions_open_idx on public.ce_world_contradictions(tenant_id,status,detected_at desc);
create table if not exists public.ce_world_state_snapshots (id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.ce_tenants(id) on delete cascade,domain text not null,state jsonb not null default '{}'::jsonb,completeness numeric(5,4) not null default 0 check(completeness>=0 and completeness<=1),confidence numeric(5,4) not null default 0 check(confidence>=0 and confidence<=1),claim_count integer not null default 0,unknown_count integer not null default 0,contradiction_count integer not null default 0,generated_at timestamptz not null default now(),model_version text not null default 'm10.2',metadata jsonb not null default '{}'::jsonb);create index if not exists ce_world_snapshots_tenant_domain_idx on public.ce_world_state_snapshots(tenant_id,domain,generated_at desc);
alter table public.ce_world_entities enable row level security;alter table public.ce_world_claims enable row level security;alter table public.ce_world_unknowns enable row level security;alter table public.ce_world_contradictions enable row level security;alter table public.ce_world_state_snapshots enable row level security;revoke all on public.ce_world_entities,public.ce_world_claims,public.ce_world_unknowns,public.ce_world_contradictions,public.ce_world_state_snapshots from anon,authenticated;grant all on public.ce_world_entities,public.ce_world_claims,public.ce_world_unknowns,public.ce_world_contradictions,public.ce_world_state_snapshots to service_role;